103	func ShadowBranches(t *testing.T, dir string) []string {
104		t.Helper()
105		branches := GitOutput(t, dir, "for-each-ref", "--format=%(refname:short)", "refs/heads/entire/")
106		var shadow []string
107		for _, b := range strings.Split(branches, "\n") {
108			b = strings.TrimSpace(b)
109			if b == "" || strings.HasPrefix(b, "entire/checkpoints") {
110				continue
111			}
112			shadow = append(shadow, b)
113		}
114		return shadow
115	}
